import{_ as e,o as i,c as s,a2 as t}from"./chunks/framework.DgVVaeR-.js";const k=JSON.parse('{"title":"ビルドと公開パイプライン","description":"","frontmatter":{"title":"ビルドと公開パイプライン"},"headers":[],"relativePath":"dev/build.md","filePath":"dev/build.md","lastUpdated":1791013521000}'),d={name:"dev/build.md"};function l(n,a,r,p,o,h){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="ビルドと公開パイプライン" tabindex="-1">ビルドと公開パイプライン <a class="header-anchor" href="#ビルドと公開パイプライン" aria-label="Permalink to &quot;ビルドと公開パイプライン&quot;">​</a></h1><p>このページは2026年10月3日に <code>app/build.gradle</code>、Gradle Wrapper、Rustクレート、GitHub Actionsを確認した内容です。設定を変更した場合はコード側の値を優先してください。</p><h2 id="開発環境" tabindex="-1">開発環境 <a class="header-anchor" href="#開発環境" aria-label="Permalink to &quot;開発環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>リポジトリの設定</th></tr></thead><tbody><tr><td>Gradle</td><td>Wrapperで9.7.1を取得</td></tr><tr><td>Gradle daemon JVM</td><td>JetBrains JDK 21（<code>gradle/gradle-daemon-jvm.properties</code>）</td></tr><tr><td>Javaソース・バイトコード</td><td>17</td></tr><tr><td>Android SDK</td><td>compileSdk 37、targetSdk 36、minSdk 24</td></tr><tr><td>Android NDK</td><td>Android StudioのSDK Managerで導入。<code>cargo-ndk</code>から参照できること</td></tr><tr><td>Rust</td><td>edition 2024対応のstableツールチェーン。依存関係はCargo.lockに従う</td></tr><tr><td>ドキュメント</td><td>Node.jsとnpm。docsのCIはNode.js 22を使用</td></tr></tbody></table><p>JDK 17というコンパイル設定と、Gradle daemonのJDK 21指定は別です。NDKの版は <code>app/build.gradle</code> で固定していません。WindowsではRustのホストビルドに必要なリンカーも用意してください。</p><h2 id="準備とビルド" tabindex="-1">準備とビルド <a class="header-anchor" href="#準備とビルド" aria-label="Permalink to &quot;準備とビルド&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yunfie-twitter/Palleria.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Palleria</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aarch64-linux-android</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> armv7-linux-androideabi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-linux-android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cargo-ndk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleDebug</span></span></code></pre></div><p>Windows PowerShellでは最後のコマンドを <code>.\\gradlew.bat :app:assembleDebug</code> に置き換えます。Android SDKの場所はAndroid Studioまたは <code>local.properties</code> で設定します。</p><p><code>preBuild</code>から次の処理が実行されます。</p><table tabindex="0"><thead><tr><th>タスク</th><th>役割</th></tr></thead><tbody><tr><td><code>buildUniFfiHost</code></td><td>ホスト用の <code>palleria_pixiv_api</code> ライブラリをビルド</td></tr><tr><td><code>generateUniFfiBindings</code></td><td><code>app/build/generated/uniffi/kotlin</code> にKotlinコードを生成</td></tr><tr><td><code>buildRustAndroid</code></td><td>3 ABIの <code>libpalleria_pixiv_api.so</code> を生成</td></tr><tr><td><code>buildPallaSyncCoreAndroid</code></td><td>3 ABIの <code>libpallasync_core.so</code> を生成</td></tr></tbody></table><p>Cargoの出力先は共通の <code>rust/target</code>、Androidの共有ライブラリの配置先は <code>app/build/generated/uniffi/jniLibs</code> です。</p><h2 id="署名付きリリース" tabindex="-1">署名付きリリース <a class="header-anchor" href="#署名付きリリース" aria-label="Permalink to &quot;署名付きリリース&quot;">​</a></h2><p><code>KEYSTORE_PATH</code>、<code>KEYSTORE_PASSWORD</code>、<code>KEY_ALIAS</code>、<code>KEY_PASSWORD</code> を設定して <code>./gradlew :app:assembleRelease</code> を実行します。相対キーストアパスはappモジュール基準です。未設定時はコード上debug署名へフォールバックするので、配布用には必ずrelease署名を用意してください。</p><p>出力は <code>app/build/outputs/apk/release/</code> 以下です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Palleria-v&lt;versionName&gt;-release-universal.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-arm64-v8a.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-armeabi-v7a.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-x86_64.apk</span></span></code></pre></div><h2 id="github-releaseとf-droid" tabindex="-1">GitHub ReleaseとF-Droid <a class="header-anchor" href="#github-releaseとf-droid" aria-label="Permalink to &quot;GitHub ReleaseとF-Droid&quot;">​</a></h2><ul><li><code>release-apk.yml</code>: mainの <code>app/build.gradle</code> 更新、<code>v*</code> タグpush、手動実行でビルドします。成功時はDraft Releaseを作成し、ビルド失敗時もタグを保持します。</li><li><code>fdroid.yml</code>: Releaseの公開・削除イベントで起動します。公開時は添付APKを取得・検証し、削除時は対応するAPKを取り除いてインデックスを更新します。</li><li><code>docs.yml</code>: ドキュメントをビルドして同じ <code>gh-pages</code> へ公開します。F-Droid更新と共通のキューで直列化し、互いの成果物を保持します。</li></ul><p>公開・復旧の詳しい手順は<a href="https://github.com/yunfie-twitter/Palleria/blob/main/.github/RELEASING.md" target="_blank" rel="noreferrer">RELEASING.md</a>を参照してください。</p><h2 id="ドキュメントの確認" tabindex="-1">ドキュメントの確認 <a class="header-anchor" href="#ドキュメントの確認" aria-label="Permalink to &quot;ドキュメントの確認&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>生成先は <code>docs/.vitepress/dist</code>、配信baseは <code>/Palleria/</code> です。ページ画像は <code>docs/assets</code> に置き、Markdownから相対パスで参照するとビルド時にURLが解決されます。</p>`,21)])])}const g=e(d,[["render",l]]);export{k as __pageData,g as default};
